		t.Fatalf("marshal payload: %v", err)
	}
	sl.writeEvent(agentcore.Event{
		SessionID: sessionID,
		Seq:       1,
		Type:      agentcore.EventReasoningStall,
		Timestamp: time.Now().UTC(),
		Data:      data,
	})
