	for _, want := range []string{
		`"type":"reasoning.stall"`,
		`"code":"REASONING_STALL"`,
		`"reasoning_tail":"thinking tail"`,
		`"prompt_id":"prompt-1"`,
	} {
		if !strings.Contains(text, want) {
			t.Fatalf("session log missing %s:\n%s", want, text)
		}
	}
}

